begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "4212d5ef-2e2f-5cc6-82ac-dfb0194f245b", "feature_slug": "rewards", "title": "Business Rules", "content": "### Core Business Rules\n\n#### Dynamic Points Rules\n1. **Multi-Dimensional Evaluation**: All four dimensions (tier, type, persona, tags) evaluated\n2. **Specificity Priority**: More specific conditions override general ones\n3. **Customer-Favorable**: Lowest points when multiple conditions match\n4. **Fallback Handling**: Configurable default or free redemption\n\n#### Redemption Rules\n1. **Multi-Quantity Support**: Redemptions support quantities from 1 to 1000\n   - Rewards WITHOUT promo codes: Creates 1 ledger record with qty=N\n   - Rewards WITH promo codes: Creates N ledger records with unique codes (qty=1 each)\n   - Atomic code reservation prevents race conditions\n   - All-or-nothing: Transaction fails if insufficient promo codes available\n2. **Positive Quantity**: Redemption quantity must be between 1 and 1000\n3. **Window Enforcement**: Redemptions outside time windows are rejected\n4. **Eligibility Priority**: All eligibility criteria must pass if specified\n5. **Points Deduction**: Atomic wallet update with audit trail\n6. **Promo Code Pool Validation**: Pre-checks availability for multi-quantity promo code rewards\n\n#### Limit Rules\n1. **Cumulative Counting**: Previous redemptions + new quantity checked against limit\n2. **Window Calculation**: Time windows calculated from current time or specific dates\n3. **Scope Independence**: User and global limits checked independently\n4. **Remaining Disclosure**: System returns how many more redemptions allowed\n\n#### Persona-Type Consistency\n1. **Validation**: Persona must be compatible with user type\n2. **Group Inheritance**: Persona groups can specify user type\n3. **Conflict Prevention**: Incompatible combinations rejected\n\n#### Persona-Aware Field Filtering\n\nThe eligibility system includes intelligent persona-aware filtering to ensure users are only validated against fields relevant to their assigned persona.\n\n**Problem Solved:**\n- Users with Persona A were being blocked for not filling fields restricted to Persona B\n- Profile completion checks now filter fields based on user''s actual persona\n- Universal fields (no persona restriction) are always validated for all users\n\n**Filtering Logic:**\n\n| User Persona | Field `persona_ids` | Include in Validation? | Reason |\n|--------------|---------------------|------------------------|--------|\n| `persona-a` | `null` or `[]` | ✅ Yes | Universal field |\n| `persona-a` | `[persona-a]` | ✅ Yes | Matches user persona |\n| `persona-a` | `[persona-b]` | ❌ No | Different persona |\n| `persona-a` | `[persona-a, persona-b]` | ✅ Yes | Includes user persona |\n| `null` | `null` or `[]` | ✅ Yes | Universal field |\n| `null` | `[persona-a]` | ❌ No | Restricted to persona |\n\n**Implementation:**\n```typescript\nfunction filterFieldsByPersona(fields: any[], userPersonaId: string | null): any[] {\n  return fields.filter(field => {\n    // Universal fields (no persona restriction) → always visible\n    if (!field.persona_ids || field.persona_ids.length === 0) {\n      return true;\n    }\n    \n    // User has no persona → skip persona-restricted fields\n    if (!userPersonaId) {\n      return false;\n    }\n    \n    // User has persona → check if it matches\n    return field.persona_ids.includes(userPersonaId);\n  });\n}\n```\n\n**Benefits:**\n- Improved UX - users not blocked by irrelevant fields\n- Accurate profile completion status per persona\n- Maintains data integrity for persona-specific information\n\n### Edge Cases & Handling\n\n#### Concurrent Redemptions\n- Row-level locking on promo codes\n- Atomic wallet operations\n- Transaction isolation for points deduction\n\n#### Multiple Matching Conditions\n- Specificity score calculation\n- Priority-based selection\n- Customer-favorable tiebreaker\n\n#### No Matching Conditions\n- Fallback points applied\n- Free redemption if allowed\n- Clear error if match required\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Reward.md#L1543 Business Rules", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "65314316582aed827772fc42befc1a52a3bd70f099adffe7c202682398cd0e21", "truncated": false}, "is_active": true}, {"id": "c3b5b314-a625-5069-b976-c9b108988c82", "feature_slug": "rewards", "title": "Implementation Status", "content": "### Multi-Quantity Redemption\n**Status:** ✅ **Deployed to Production**  \n**Implementation Date:** February 3, 2026  \n**Services Updated:**\n- Supabase Function: `redeem_reward_with_points` - supports quantity parameter (1-1000)\n- Render API (`crm-api`): Validates and passes quantity through Kafka\n- Event Processor (`crm-event-processors`): Extracts quantity from events\n\n**Key Features:**\n- Smart branching: Single record for non-promo rewards, multiple records for promo code rewards\n- Atomic promo code reservation with `FOR UPDATE SKIP LOCKED`\n- All-or-nothing transaction semantics\n- Backward compatible (quantity defaults to 1)\n\n### Persona-Aware Field Filtering\n**Status:** ✅ **Deployed to Production**  \n**Implementation Date:** February 8, 2026  \n**Function:** `bff-auth-complete` (Edge Function v54)\n\n**Key Features:**\n- Filters profile completion checks by user''s assigned persona\n- Universal fields always validated for all users\n- Persona-restricted fields only checked for matching users\n- Improved UX - users not blocked by irrelevant profile fields\n\n**Monitoring:**\n- Log entries: `[PERSONA_FILTER] User persona: <uuid>`\n- Success metric: More users reaching `next_step: \"complete\"`\n- Profile completion rates tracked per persona\n\n### Promo Code Redemption UUID Fix\n**Status:** ✅ **Deployed to Production**  \n**Implementation Date:** February 16, 2026  \n**Migration:** `fix_promo_code_redemption_uuid`  \n**Function:** `redeem_reward_with_points()` - Fixed UUID generation for event-based idempotency\n\n**Issue Resolved:**\n- **Bug**: Event processor failed with `invalid input syntax for type uuid` when redeeming promo code rewards\n- **Root Cause**: Function attempted to create UUID by appending suffix (e.g., `event_id-1`) for quantity loops\n- **Impact**: 100% failure rate for rewards with `assign_promocode = true`\n\n**Fix Implementation:**\n\n**1. Added Business Rule Validation:**\n```sql\n-- Enforce single quantity for promo code rewards\nIF v_reward.assign_promocode AND p_quantity > 1 THEN\n    RETURN jsonb_build_object(\n        ''success'', false,\n        ''title'', ''Invalid quantity for promo code reward'',\n        ''description'', ''Rewards with unique promo codes can only be redeemed one at a time.''\n    );\nEND IF;\n```\n\n**2. Fixed UUID Generation Logic:**\n```sql\n-- Before (Buggy):\nv_record_id := (p_event_id::text || ''-'' || i)::uuid;  -- Invalid format!\n\n-- After (Fixed):\nIF p_event_id IS NOT NULL AND v_reward.assign_promocode THEN\n    v_record_id := p_event_id;  -- Use event_id directly (qty always 1)\nELSIF p_event_id IS NOT NULL THEN\n    v_record_id := (p_event_id::text || ''-'' || i)::uuid;  -- Multi-qty non-promo\nELSE\n    v_record_id := gen_random_uuid();  -- Fallback\nEND IF;\n```\n\n**Key Technical Details:**\n\n**Event-Driven Idempotency Pattern:**\n- Render API generates `event_id` (UUID) and publishes to Kafka\n- Event processor passes `event_id` as `p_event_id` to Supabase function\n- Function uses `event_id` as the redemption record ID for idempotency\n- Duplicate events return existing record instead of creating new one\n\n**Promo Code Assignment Flow (Atomic Transaction):**\n```sql\nBEGIN;\n    -- 1. SELECT and LOCK available code\n    SELECT id, promo_code FROM reward_promo_code\n    WHERE reward_id = $1 AND redeemed_status = false\n    LIMIT 1 FOR UPDATE SKIP LOCKED;\n    \n    -- 2. UPDATE promo code status\n    UPDATE reward_promo_code \n    SET redeemed_status = true \n    WHERE id = $1;\n    \n    -- 3. INSERT redemption record\n    INSERT INTO reward_redemptions_ledger (\n        id, promo_code, ...\n    ) VALUES (\n        p_event_id,  -- Use event_id directly\n        $promo_code, -- Assigned code\n        ...\n    );\nCOMMIT;\n```\n\n**UUID Generation Rules:**\n- **Promo code rewards (qty=1)**: Use `p_event_id` directly\n- **Standard rewards (qty=1)**: Use `p_event_id` directly  \n- **Standard rewards (qty>1)**: Use `p_event_id` with suffix if provided, else `gen_random_uuid()`\n- **Direct calls (no event_id)**: Always use `gen_random_uuid()`\n\n**Error Handling:**\n- **Transient errors** (network, locks): Retry with exponential backoff (max 5 attempts)\n- **Permanent errors** (validation, eligibility, insufficient codes): No retry, return error immediately\n- **Concurrent conflicts**: `SKIP LOCKED` prevents deadlocks, moves to next available code\n\n**Testing Results:**\n- Promo code redemptions: ✅ Fixed (was 100% failure, now 100% success)\n- Standard redemptions: ✅ Unchanged (0% regression)\n- Processing time: ~100-200ms per redemption\n- Concurrent safety: ✅ Multiple users can redeem simultaneously\n\n**Monitoring:**\n- Render logs: `[RewardConsumer] Successfully processed event {id} in {time}ms`\n- Database: Promo codes marked as `redeemed_status = true`\n- Redemption ledger: Promo codes populated in `promo_code` field\n\n---\n\n### Shopify Discount Product Lookup\n**Status:** ✅ **Deployed to Production**  \n**Implementation Date:** March 13, 2026  \n**Functions:**\n- `shopify-get-discount-products` (Edge Function) — Core Shopify product lookup\n- `bff-mark-redemption-used` (Edge Function) — Wraps `api_mark_redemption_used` + Shopify enrichment\n- `bff-get-redemption-detail` (Edge Function) — Redemption detail query + Shopify enrichment\n\n**Purpose:**\nFor rewards linked to a Shopify discount (via `reward_master.external_id_shopify`), fetch the actual product details from the Shopify Price Rule — product names, images, prices, and discount type — and include them in the \"mark as used\" and \"get redemption detail\" responses.\n\n**Architecture:**\n```\nbff-mark-redemption-used ──┐\n                           ├──→ shopify-get-discount-products ──→ Shopify REST API\nbff-get-redemption-detail ─┘\n```\n\nBoth BFF functions call `shopify-get-discount-products` centrally. All Shopify logic (credential lookup, Price Rule fetch, product fetch, response mapping) lives in one function.\n\n**How It Works:**\n1. BFF function executes its primary operation (mark as used / query ledger)\n2. Checks `reward_master.external_id_shopify` — if null, skip (zero overhead for non-Shopify rewards)\n3. Calls `shopify-get-discount-products` with `merchant_id` + `reward_id`\n4. `shopify-get-discount-products`:\n   - Looks up Shopify credentials from `merchant_credentials` (service_name = `shopify_app`)\n   - Calls Shopify REST API `GET /price_rules/{id}.json` to get discount details\n   - Determines discount type: `free_product`, `percentage`, `fixed_amount`, or `free_shipping`\n   - If entitled products exist: calls `GET /products.json?ids=...` for product details\n   - If entitled collections exist: calls `GET /collections/{id}/products.json` for each\n   - If `target_selection = \"all\"` or `target_type = \"shipping_line\"`: returns `has_products: false` (bill-level discount)\n5. Product details merged into BFF response as `shopify_discount_detail`\n\n**Shopify Discount Type Handling:**\n\n| Scenario | `target_selection` | `target_type` | `has_products` | `discount_type` |\n|---|---|---|---|---|\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Reward.md#L2477 Implementation Status", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a44e0a19013badccb5dff86a8f2923e13e590508949c550af80705a93a304f15", "truncated": true}, "is_active": true}, {"id": "f8654e38-f65f-518e-9d4a-6236cebd240e", "feature_slug": "rewards", "title": "7. Business Rules", "content": "**Rule:** Eligibility is evaluated before points — a member must pass all eligibility filters before the system calculates cost.\n**Example:** Member is Silver tier, reward allows only Gold+ → blocked before points are even checked.\n\n**Rule:** Dynamic pricing uses specificity-first matching. A condition matching 3 dimensions always beats one matching 2, regardless of priority values.\n**Example:** \"Gold + Student + VIP = 30 pts\" (specificity 3) beats \"Gold + Student = 40 pts\" (specificity 2) even if the latter has higher priority.\n\n**Rule:** When multiple conditions have identical specificity and priority, the system selects the lowest points cost (customer-favorable).\n**Example:** Two conditions both match Gold tier at priority 100: one says 60 pts, one says 80 pts → member pays 60.\n\n**Rule:** Fallback points apply only when zero conditions match the member. If at least one condition matches, fallback is ignored.\n**Example:** Reward has Gold=60pts, fallback=100pts. Silver member (no match) → pays 100. Gold member → pays 60.\n\n**Rule:** Redemptions are all-or-nothing for multi-quantity with promo codes. If the pool has fewer codes than requested, the entire transaction fails — no partial redemption.\n**Example:** Member requests qty=10, only 7 codes available → error, zero codes assigned, zero points deducted.\n\n**Rule:** Redemption is async. The API returns an `event_id` immediately; the actual transaction is processed by an event consumer. The frontend subscribes to Realtime for the result.\n**Example:** Member clicks \"Redeem\" → sees spinner → Realtime pushes success with redemption details → UI updates.\n\n**Rule:** \"Save and Publish\" overrides visibility to `user`, regardless of the visibility dropdown value at save time.\n**Example:** Admin sets visibility to `campaign`, clicks \"Save and Publish\" → reward becomes `user` (public).\n\n**Rule:** Empty eligibility arrays mean unrestricted. `allowed_tier = []` means all tiers qualify, not zero tiers.\n**Example:** Reward with no tier filter → Bronze through Diamond can all redeem.\n\n**Rule:** Transaction limits are cumulative. A new redemption''s quantity is added to previous redemptions in the window before checking the cap.\n**Example:** Limit = 5/month, member already redeemed 3 this month, requests qty=3 → blocked (3+3=6 > 5).\n\n**Rule:** Promo codes are reserved atomically using `FOR UPDATE SKIP LOCKED` to prevent race conditions between concurrent redemptions.\n**Example:** Two members redeem simultaneously, 1 code left → exactly one succeeds, the other gets \"insufficient codes.\"\n\n**Rule:** Expiration is calculated at redemption time based on the expire mode. `relative_days = 30` means the expiry is set to 30 days from the moment of redemption, not from reward creation.\n**Example:** Reward created Jan 1, member redeems Mar 15 → expires Apr 14.\n\n**Rule:** The user-facing catalog (`api_get_rewards_full_cached`) returns only `visibility = ''user''` rewards. `admin` and `campaign` rewards are excluded.\n**Example:** Admin creates a reward with `visibility = ''campaign''` → members never see it in the browse catalog. It can only reach members through AMP push or admin assignment.\n\n**Rule:** Cached reward catalog has a 5-minute TTL. Changes to rewards, stock, or promo codes trigger cache invalidation, but there may be up to 5 minutes of stale data in normal operation.\n**Example:** Admin adds stock → members may see old stock count for up to 5 minutes.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/rewards.md#L360 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5c6b179ad0d14e811afbe655d15bcc1a42a3dcd4af205e61707c75cef185a6e1", "truncated": false}, "is_active": true}, {"id": "29699b03-f1f2-53f0-badb-b3adc2a2d257", "feature_slug": "rewards", "title": "3. Configuration Reference", "content": "### Basic Info\n\n\n| Setting               | What it controls                           | Example               | Default          |\n| --------------------- | ------------------------------------------ | --------------------- | ---------------- |\n| Name                  | Reward display name                        | \"Free Coffee Voucher\" | Required         |\n| Category              | Organizational grouping                    | \"Food & Beverage\"     | None             |\n| Redemption start date | Earliest date members can redeem           | 2025-01-01            | No restriction   |\n| Redemption end date   | Latest date members can redeem             | 2025-12-31            | No restriction   |\n| Expire mode           | How redeemed rewards expire                | `relative_days`       | None (no expiry) |\n| Expire TTL            | Days/minutes until expiry (relative modes) | 30                    | —                |\n| Expire date           | Fixed expiry date (absolute mode)          | 2025-06-30            | —                |\n\n\n### Eligibility Conditions\n\n\n| Setting              | What it controls                 | Example              | Default            |\n| -------------------- | -------------------------------- | -------------------- | ------------------ |\n| Allowed tiers        | Which tier members can redeem    | [Gold, Platinum]     | Empty = all tiers  |\n| Allowed personas     | Which persona members can redeem | [Student, Corporate] | Empty = all        |\n| Allowed birth months | Birthday-reward targeting        | [1, 12] (Jan, Dec)   | Empty = all months |\n\n\n### Points Pricing\n\n\n| Setting                  | What it controls                                 | Example                      | Default                      |\n| ------------------------ | ------------------------------------------------ | ---------------------------- | ---------------------------- |\n| Require points match     | If true, member MUST match a condition to redeem | true                         | false                        |\n| Fallback points          | Points cost when no condition matches            | 100                          | null (free if no conditions) |\n| Points conditions        | Rows of tier/persona/type/tags → points mappings | Gold: 60 pts, Silver: 80 pts | Empty                        |\n| Priority (per condition) | Tiebreaker when specificity is equal             | 150                          | 100                          |\n\n\n### Transaction Limits\n\n\n| Setting          | What it controls               | Example    | Default   |\n| ---------------- | ------------------------------ | ---------- | --------- |\n| Scope            | Who the limit applies to       | `per_user` | —         |\n| Time unit        | Period of the limit            | `month`    | —         |\n| Count            | Maximum redemptions in period  | 3          | —         |\n| Window start/end | Optional date range for limit  | 2025-Q1    | No window |\n| Active status    | Enable/disable this limit rule | true       | true      |\n\n\n### Display Settings\n\n\n| Setting              | What it controls                           | Example                             | Default |\n| -------------------- | ------------------------------------------ | ----------------------------------- | ------- |\n| Description headline | Short title shown on reward detail         | \"Exclusive Coffee Offer\"            | Empty   |\n| Image                | Reward image (single URL, stored as array) | PNG/JPG/WEBP, max 5MB               | None    |\n| Description body     | Rich HTML description                      | Full reward details                 | Empty   |\n| Terms & conditions   | Rich HTML T&C                              | Redemption rules, restrictions      | Empty   |\n| Redemption slip      | Rich HTML slip text                        | Instructions shown after redemption | Empty   |\n\n\n### Sidebar Controls\n\n\n| Setting            | What it controls                         | Example         | Default |\n| ------------------ | ---------------------------------------- | --------------- | ------- |\n| Visibility         | Catalog visibility level                 | `user` (public) | `admin` |\n| Assign promo code  | Pull unique codes from pool on redeem    | true            | false   |\n| Stock control      | Enable finite inventory                  | true            | false   |\n| Fulfillment method | Delivery type (shown when stock enabled) | `digital`       | None    |\n\n\n### Marketplace Distribution\n\n\n| Setting                   | What it controls                    | Example                | Default |\n| ------------------------- | ----------------------------------- | ---------------------- | ------- |\n| Ecommerce platform toggle | Link reward to external storefronts | true                   | false   |\n| Platforms                 | Which storefronts (multi-select)    | [shopify, bigcommerce] | —       |\n| Shopify discount code     | Bind to a specific Shopify discount | \"SUMMER2025\"           | None    |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/rewards.md#L49 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f240d6c2d2ddb368fbca0bd075b1caa0fcd23803794ffff27b6fe84d353c8b14", "truncated": false}, "is_active": true}, {"id": "2420f7c6-31f2-5916-858b-6157f75c2a5f", "feature_slug": "rewards", "title": "System Health & Monitoring", "content": "### Key Metrics to Monitor\n\n#### Points Calculation Metrics\n- Average calculation time\n- Condition match rates\n- Fallback usage frequency\n- Most common condition matches\n\n#### Redemption Metrics\n- Total redemptions per day/hour\n- Average points per redemption\n- Points deducted by tier/persona\n- Failed redemption attempts\n- **Multi-Quantity Metrics**:\n  - Quantity distribution (% with qty=1 vs qty>1)\n  - Average quantity per redemption\n  - Multi-quantity redemptions by reward type\n  - Promo code pool depletion rate\n\n#### Configuration Health\n- Rewards without conditions\n- Conditions without matches\n- Conflicting persona-type configurations\n- Unused conditions\n\n### Health Check Queries\n\n```sql\n-- Check points configuration coverage\nSELECT * FROM v_points_conditions_coverage;\n\n-- Monitor points calculation performance\nSELECT \n    reward_id,\n    AVG(calculation_time_ms) as avg_time,\n    COUNT(*) as calculations,\n    SUM(CASE WHEN match_type = ''fallback'' THEN 1 ELSE 0 END) as fallback_count\nFROM redemption_metrics\nWHERE created_at >= NOW() - INTERVAL ''24 hours''\nGROUP BY reward_id;\n\n-- Analyze condition usage\nSELECT \n    rpc.condition_name,\n    COUNT(DISTINCT rrl.user_id) as unique_users,\n    SUM(rrl.points_deducted) as total_points,\n    AVG(rrl.points_deducted) as avg_points\nFROM reward_redemptions_ledger rrl\nJOIN reward_points_conditions rpc ON rpc.id = (rrl.points_calculation->>''condition_id'')::uuid\nWHERE rrl.created_at >= NOW() - INTERVAL ''7 days''\nGROUP BY rpc.condition_name\nORDER BY unique_users DESC;\n\n-- Monitor multi-quantity redemption patterns\nSELECT \n    r.name as reward_name,\n    COUNT(*) as total_redemptions,\n    SUM(rrl.qty) as total_units_redeemed,\n    AVG(rrl.qty) as avg_quantity,\n    COUNT(CASE WHEN rrl.qty > 1 THEN 1 END) as multi_qty_redemptions,\n    ROUND(100.0 * COUNT(CASE WHEN rrl.qty > 1 THEN 1 END) / COUNT(*), 2) as multi_qty_percentage\nFROM reward_redemptions_ledger rrl\nJOIN reward_master r ON r.id = rrl.reward_id\nWHERE rrl.created_at >= NOW() - INTERVAL ''7 days''\n  AND rrl.redeemed_status = true\nGROUP BY r.id, r.name\nORDER BY total_units_redeemed DESC;\n\n-- Monitor promo code pool health (alert when low)\nSELECT \n    r.name as reward_name,\n    COUNT(*) as total_codes,\n    COUNT(CASE WHEN rpc.redeemed_status = false THEN 1 END) as available_codes,\n    COUNT(CASE WHEN rpc.redeemed_status = true THEN 1 END) as used_codes,\n    ROUND(100.0 * COUNT(CASE WHEN rpc.redeemed_status = true THEN 1 END) / COUNT(*), 2) as usage_percentage\nFROM reward_promo_code rpc\nJOIN reward_master r ON r.id = rpc.reward_id\nWHERE r.assign_promocode = true\nGROUP BY r.id, r.name\nHAVING COUNT(CASE WHEN rpc.redeemed_status = false THEN 1 END) < 50\nORDER BY available_codes ASC;\n```\n\n---", "content_format": "markdown", "knowledge_type": "implementation_constraints", "perspectives": ["implementation", "technical", "testing"], "output_uses": ["implementation_brief", "qa_testing", "technical_docs"], "scope": "be", "source_ref": "requirements/Reward.md#L2189 System Health & Monitoring", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "constraints", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c0f5c35fc4c0bbb8833b5b914e5b6f626cb86eeb4589cad651c37efd8cc5ef12", "truncated": false}, "is_active": true}, {"id": "c7004084-592f-54c8-b42d-d6af37b2b53b", "feature_slug": "rewards", "title": "API Integration", "content": "### Calculate Points (Preview)\n```http\nGET /api/rewards/{reward_id}/points?user_id={user_id}\n```\n\n**Response**:\n```json\n{\n  \"reward_id\": \"uuid\",\n  \"user_id\": \"uuid\",\n  \"points_calculation\": {\n    \"success\": true,\n    \"points_required\": 50,\n    \"match_type\": \"condition\",\n    \"condition_name\": \"Gold VIP Rate\",\n    \"match_details\": {\n      \"tier_match\": true,\n      \"type_match\": false,\n      \"persona_match\": false,\n      \"tags_match\": true,\n      \"specificity\": 2,\n      \"priority\": 150\n    },\n    \"user_attributes\": {\n      \"tier\": \"Gold\",\n      \"user_type\": \"buyer\",\n      \"persona\": \"Student\",\n      \"tags\": [\"VIP\", \"Early Adopter\"]\n    }\n  },\n  \"user_eligible\": true,\n  \"points_available\": 500\n}\n```\n\n### Redeem Reward\n```http\nPOST /api/rewards/{reward_id}/redeem\n```\n\n**Request**:\n```json\n{\n  \"user_id\": \"uuid\",\n  \"quantity\": 5,\n  \"delivery_address_code\": \"addr_123\"\n}\n```\n\n**Response (Success - WITHOUT Promo Codes)**:\n```json\n{\n  \"success\": true,\n  \"message\": \"Successfully redeemed 5 reward(s)\",\n  \"redemption_codes\": [\"RWD000123\"],\n  \"points_deducted\": 250,\n  \"points_remaining\": 250,\n  \"quantity\": 5,\n  \"expires_at\": \"2024-02-01T23:59:59Z\",\n  \"points_calculation\": {\n    \"condition_matched\": \"Gold VIP Rate\",\n    \"points_per_unit\": 50,\n    \"total_points\": 250\n  }\n}\n```\n\n**Response (Success - WITH Promo Codes)**:\n```json\n{\n  \"success\": true,\n  \"message\": \"Successfully redeemed 5 reward(s)\",\n  \"redemption_codes\": [\"RWD000123\", \"RWD000124\", \"RWD000125\", \"RWD000126\", \"RWD000127\"],\n  \"promo_codes\": [\"CODE-ABC123\", \"CODE-DEF456\", \"CODE-GHI789\", \"CODE-JKL012\", \"CODE-MNO345\"],\n  \"points_deducted\": 250,\n  \"points_remaining\": 250,\n  \"quantity\": 5,\n  \"expires_at\": \"2024-02-01T23:59:59Z\",\n  \"points_calculation\": {\n    \"condition_matched\": \"Gold VIP Rate\",\n    \"points_per_unit\": 50,\n    \"total_points\": 250\n  }\n}\n```\n\n**Response (Insufficient Points)**:\n```json\n{\n  \"success\": false,\n  \"message\": \"Insufficient points. Required: 750, Available: 100\",\n  \"points_required\": 750,\n  \"points_available\": 100,\n  \"quantity\": 5,\n  \"points_calculation\": {\n    \"condition_matched\": \"Silver Member Rate\",\n    \"points_per_unit\": 150,\n    \"total_points\": 750\n  }\n}\n```\n\n**Response (Insufficient Promo Codes)**:\n```json\n{\n  \"success\": false,\n  \"error_code\": \"INSUFFICIENT_CODES\",\n  \"message\": \"Only 7 code(s) available, you requested 10\",\n  \"available_codes\": 7,\n  \"requested_quantity\": 10\n}\n```\n\n### Preview User Rewards\n```http\nGET /api/users/{user_id}/rewards/available\n```\n\n**Response**:\n```json\n{\n  \"rewards\": [\n    {\n      \"reward_id\": \"uuid\",\n      \"name\": \"Premium Voucher\",\n      \"points_required\": 50,\n      \"match_type\": \"condition\",\n      \"condition_name\": \"Gold VIP Rate\",\n      \"user_eligible\": true,\n      \"can_afford\": true\n    },\n    {\n      \"reward_id\": \"uuid\", \n      \"name\": \"Exclusive Item\",\n      \"points_required\": 200,\n      \"match_type\": \"fallback\",\n      \"user_eligible\": true,\n      \"can_afford\": false\n    }\n  ],\n  \"user_points_balance\": 150\n}\n```\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Reward.md#L1640 API Integration", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "4b37b3e4c98b474302361ceb87fc616efdb8fce25451165cbded7e455dc40285", "truncated": false}, "is_active": true}, {"id": "1b6d236f-071b-562c-a4ed-f152442e8728", "feature_slug": "rewards", "title": "API Integration", "content": "### RPC Functions\n\n#### Core Redemption Functions\n\n**`redeem_reward_with_points(user_id, reward_id, qty)`**:\n- Orchestrates complete redemption flow\n- Validates eligibility, calculates points, deducts balance\n- Assigns promo codes from pool if configured\n- Returns redemption details including codes and expiry\n- Frontline/admin redemptions with `p_store_id` or `p_source_type=''admin_frontline''` write one `redemption_usage_log` row per created redemption with `action=''redeem''`, the selected store, `performed_by=auth.uid()::text`, and `admin_user_id` when the actor is an admin/staff user.\n\n**Frontline redemption audit**:\n- `api_get_redemption(..., p_store_id)` validates the store belongs to the merchant before writing a lookup audit row.\n- `admin_redeem_and_use` relies on `redeem_reward_with_points` for the redeem audit and writes the use audit itself.\n- `admin_mark_redemptions_used` and `api_mark_redemption_used` keep `used_store_id` and `redemption_usage_log.store_id`; admin/staff actors are resolved through `redemption_usage_log.admin_user_id`.\n- `admin_get_user_redemptions` and `api_get_redemption` return the existing `redeemed_by_*` / `used_by_*` fields, preferring the `redeem` audit actor over lookup-only history, resolving `admin_users.name` for staff actions first, then falling back to `user_accounts.fullname`.\n\n**`calculate_redemption_points(user_id, reward_id)`**:\n- Preview points required without redeeming\n- Shows matched condition and calculation details\n- Useful for shopping cart displays\n\n**`check_reward_eligibility_enhanced(user_id, reward_id)`**:\n- Comprehensive eligibility validation\n- Returns specific rejection reasons\n- Checks tier, persona, tags, time windows, stock\n\n#### Promo Code Management Functions\n\n**`bulk_upload_promo_codes(codes[], reward_id, batch_name)`**:\n- Batch import with automatic deduplication\n- Supports partner attribution and lot codes\n- Returns upload statistics and duplicate report\n\n**`get_promo_code_summary()`**:\n- Aggregated view of promo code batches\n- Shows availability, redemption rates, partner performance\n- Filtered by merchant context automatically\n\n### REST API Endpoints\n\n#### Get Available Rewards\n```http\nGET /rewards/available\nAuthorization: Bearer {token}\n\nResponse:\n{\n    \"rewards\": [\n        {\n            \"id\": \"reward_uuid\",\n            \"name\": \"Premium Voucher\",\n            \"description\": \"Exclusive access voucher\",\n            \"image_urls\": [\"https://...\"],\n            \"points_required\": 50,\n            \"eligibility\": {\n                \"is_eligible\": true,\n                \"can_afford\": true\n            },\n            \"availability\": {\n                \"stock_remaining\": 100,\n                \"user_limit_remaining\": 3,\n                \"expires_in_days\": 30\n            },\n            \"fulfillment_method\": \"digital\"\n        }\n    ],\n    \"user_balance\": {\n        \"points\": 500,\n        \"tier\": \"Gold\",\n        \"persona\": \"Corporate\"\n    }\n}\n```\n\n#### Redeem Reward\n```http\nPOST /rewards/{reward_id}/redeem\nAuthorization: Bearer {token}\nContent-Type: application/json\n\n{\n    \"quantity\": 1,\n    \"delivery_address_code\": \"addr_123\",\n    \"request_id\": \"req_abc123\"  // For idempotency\n}\n\nResponse:\n{\n    \"success\": true,\n    \"redemption_id\": \"red_uuid\",\n    \"redemption_code\": \"RWD000001\",\n    \"promo_code\": \"SPECIAL2024\",\n    \"points_deducted\": 50,\n    \"new_balance\": 450,\n    \"expires_at\": \"2024-12-31T23:59:59Z\",\n    \"fulfillment\": {\n        \"method\": \"digital\",\n        \"status\": \"pending\",\n        \"instructions\": \"Code will be sent via email\"\n    }\n}\n```\n\n#### Get Redemption History\n```http\nGET /users/{user_id}/redemptions\nAuthorization: Bearer {token}\n\nResponse:\n{\n    \"redemptions\": [\n        {\n            \"id\": \"red_uuid\",\n            \"reward_name\": \"Premium Voucher\",\n            \"redeemed_at\": \"2024-01-15T10:30:00Z\",\n            \"points_spent\": 50,\n            \"status\": \"redeemed\",\n            \"promo_code\": \"SPECIAL2024\",\n            \"expires_at\": \"2024-12-31T23:59:59Z\",\n            \"fulfillment_status\": \"completed\",\n            \"quantity\": 1\n        }\n    ],\n    \"pagination\": {\n        \"page\": 1,\n        \"per_page\": 20,\n        \"total_pages\": 5,\n        \"total_count\": 98\n    }\n}\n```\n\n#### Listen for Redemption Results (Realtime)\n\nSince redemption processing is asynchronous, frontend subscribes to a **single Supabase Realtime channel** with two listeners — one for success (database INSERT) and one for failure (Broadcast):\n\n```javascript\nconst channel = supabase.channel(`redemption:${userId}`)\n\n// SUCCESS — Supabase Realtime postgres_changes on ledger INSERT\nchannel.on(\n  ''postgres_changes'',\n  {\n    event: ''INSERT'',\n    schema: ''public'',\n    table: ''reward_redemptions_ledger'',\n    filter: `user_id=eq.${userId}`,\n  },\n  (payload) => {\n    const redemption = payload.new;\n    if (redemption.promo_code) {\n      showSuccess(`Redeemed! Code: ${redemption.promo_code}`);\n    } else {\n      showSuccess(`Redeemed ${redemption.qty} item(s)!`);\n    }\n  }\n)\n\n// FAILURE — Supabase Realtime Broadcast (no database write, ephemeral)\n// Event Processor sends this via HTTP when redemption fails validation\nchannel.on(\n  ''broadcast'',\n  { event: ''redemption_failed'' },\n  ({ payload }) => {\n    // payload: { event_id, reward_id, title, description }\n    showError(payload.title, payload.description);\n    // e.g. \"Personal redemption limit reached\", \"Limit: 1 per year. Used: 1.\"\n  }\n)\n\nchannel.subscribe()\n\n// Timeout fallback — if neither event arrives within 15s\nsetTimeout(() => {\n  if (!resultReceived) {\n    showInfo(''Redemption is being processed. Check your rewards history.'');\n  }\n}, 15000);\n```\n\n**Broadcast payload shape** (sent by Event Processor on failure):\n```json\n{\n  \"event_id\": \"uuid\",\n  \"reward_id\": \"uuid\",\n  \"title\": \"Personal redemption limit reached\",\n  \"description\": \"Limit: 1 per year. Used: 1. Requested: 1.\"\n}\n```\n\n**For Multi-Quantity with Promo Codes**: Frontend will receive N separate INSERT events (one per unique code assigned).\n\n**Important**: The failure broadcast is ephemeral — not stored anywhere. If the user disconnects before the message arrives, they won''t see it. This is safe because failed redemptions make no database changes (no points deducted, no records created).\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Reward.md#L1788 API Integration", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "b29ebd29ed8f0bc20399a087fb52aedf5c0f076dd41d02d8fa2453b379bcc4ba", "truncated": false}, "is_active": true}, {"id": "1080b17a-5d98-5510-85b2-a25db2812d73", "feature_slug": "rewards", "title": "Store Stock Functions", "content": "- `fn_get_reward_store_stock(p_reward_id, p_merchant_id)` returns configured store allocations with derived `used_qty` and `available_stock`.\n- `fn_check_reward_store_stock_on_use(p_redemption_id, p_store_id)` validates claim/use availability.\n- `bff_get_reward_store_stock(p_reward_id)` loads store stock for admin reward setup.\n- `bff_upsert_reward_store_stock(p_reward_id, p_store_stock)` replaces store stock rows for admin reward setup.", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Reward.md#L18 Store Stock Functions", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "44030ded87e0e096a65aa1af7f2d3de894b71103a770c19d4843ed933408fa67", "truncated": false}, "is_active": true}, {"id": "bfa05964-3dff-5e6f-852e-cb4a4125fe37", "feature_slug": "rewards", "title": "Table of Contents", "content": "- [Core Concepts & Glossary](#core-concepts--glossary)\n- [Business Requirements](#business-requirements)\n- [System Architecture](#system-architecture)\n- [Database Schema](#database-schema)\n- [Dynamic Points Calculation Engine](#dynamic-points-calculation-engine)\n- [Reward Redemption Processing](#reward-redemption-processing)\n- [Eligibility & Validation System](#eligibility--validation-system)\n- [Promo Code Management](#promo-code-management)\n- [Fulfillment & Delivery Management](#fulfillment--delivery-management)\n- [Business Rules](#business-rules)\n- [API Integration](#api-integration)\n- [Implementation Examples](#implementation-examples)\n- [System Operations & Monitoring](#system-operations--monitoring)\n\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Reward.md#L39 Table of Contents", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "2568e73db611a7bae989e1d9cc1f67ac75738ce10f86e9032878bdfea6f818a7", "truncated": false}, "is_active": true}, {"id": "6fb39f84-9c03-537b-9102-89d1ffae2145", "feature_slug": "rewards", "title": "Database Schema", "content": "### Schema Design Principles\n\n1. **Separation of Concerns**: Rewards, conditions, and redemptions in separate tables\n2. **Audit Trail**: Complete history in ledger tables\n3. **Idempotency**: Natural keys prevent duplicate operations\n4. **Consistency**: Foreign key constraints maintain referential integrity\n5. **Performance**: Optimized indexes for common query patterns\n6. **Two-Layer Architecture**: Materialized views for aggregation, regular views for real-time data\n\n### Core Tables\n\n#### Table: `reward_master`\n**Purpose**: Central repository for all reward definitions with comprehensive configuration\n\n```sql\nCREATE TABLE reward_master (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    merchant_id UUID NOT NULL,\n    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n    \n    -- Basic Information\n    name TEXT,\n    description_headline TEXT,\n    description_body TEXT,\n    description_tc TEXT,        -- Terms & Conditions\n    description_slip TEXT,       -- Redemption slip text\n    image TEXT[],               -- Array of image URLs\n    \n    -- Categorization\n    group_id UUID[],            -- Reward groups\n    category_id UUID[],         -- Reward categories\n    ranking SMALLINT,           -- Display order\n    \n    -- Eligibility Rules (Layer 1: WHO can redeem)\n    allowed_tier UUID[],        -- Eligible tier IDs\n    allowed_type UUID[],        -- Eligible user type IDs\n    allowed_persona UUID[],     -- Eligible persona IDs (NEW)\n    allowed_tags UUID[],        -- Required tag IDs (NEW)\n    allowed_birthmonth TEXT[],  -- Eligible birth months (1-12)\n    \n    -- Points Configuration (Layer 2: HOW MANY points)\n    fallback_points NUMERIC,    -- Default points if no condition matches (NEW)\n    require_points_match BOOLEAN DEFAULT false, -- If true, must match a condition (NEW)\n    \n    -- Redemption Configuration\n    visibility reward_visibility,\n    redeem_window_start TIMESTAMPTZ,\n    redeem_window_end TIMESTAMPTZ,\n    \n    -- Inventory & Codes\n    stock_control BOOLEAN,\n    assign_promocode BOOLEAN,\n    promo_code TEXT,            -- Default promo code if not unique\n    \n    -- Expiration Settings\n    use_expire_mode reward_expire_mode,\n    use_expire_date TIMESTAMPTZ,    -- For absolute_date mode\n    use_expire_ttl NUMERIC,          -- For relative modes\n    \n    -- Fulfillment\n    fulfillment_method reward_fulfillment_method,\n    \n    -- Marketplace Distribution\n    online_store TEXT[],             -- Storefronts to display on (e.g. ''shopify'', ''bigcommerce'', ''lazada'')\n    \n    -- Reward Group Membership\n    reward_group_ids UUID[]          -- Array of reward_group IDs this reward belongs to\n);\n```\n\n#### Table: `reward_group`\n**Purpose**: Groups multiple rewards together for shared redemption limit enforcement\n\n```sql\nCREATE TABLE reward_group (\n    id          UUID        PRIMARY KEY DEFAULT gen_random_uuid(),\n    merchant_id UUID        NOT NULL REFERENCES merchant_master(id),\n    group_code  TEXT,                   -- Human-readable identifier (unique per merchant)\n    name        TEXT        NOT NULL,   -- Display name\n    description TEXT,\n    is_active   BOOLEAN     DEFAULT true,\n    created_at  TIMESTAMPTZ DEFAULT now(),\n    updated_at  TIMESTAMPTZ DEFAULT now()\n);\n```\n\n**Group Limits** are stored in `transaction_limits` with `entity_type = ''reward_group''` and `entity_id = reward_group.id`. Same scope/time_unit options as per-reward limits (user/total, day/week/month/year/all_time).\n\n**Relationship**: `reward_master.reward_group_ids UUID[]` — a reward can belong to multiple groups. Group membership is assigned on the reward config form.\n\n**Limit Enforcement**: During redemption (`redeem_reward_with_points`), after per-reward limit checks, the system calls `fn_check_reward_group_limits` which:\n1. Loads the reward''s `reward_group_ids`\n2. For each active group, loads limits from `transaction_limits`\n3. Counts redemptions across ALL rewards in the group (sibling rewards)\n4. Blocks redemption if any group limit would be exceeded\n\n#### Three Limit Concepts (`transaction_limits.metric`)\n\nThe `transaction_limits` table carries a `metric` column (enum `reward_limit_metric`) that determines **what** `count` is measuring. Combined with `entity_type`, this yields three distinct concepts merchants can configure:\n\n| Concept | `entity_type` | `metric` | `scope` | What `count` means |\n|---|---|---|---|---|\n| **Reward Quota Limit** | `reward` | `quantity` | `user` / `total` | Total units of **this one reward** a user (or everyone) may redeem |\n| **Group Quantity Limit** | `reward_group` | `quantity` | `user` / `total` | Total units redeemed across **all rewards** in the group combined |\n| **Max Distinct Reward** | `reward_group` | `distinct_reward` | `user` only | Number of **distinct reward types** a user may pick inside the group |\n\n**Max Distinct Reward** (introduced April 2026) answers the business case \"User can pick 2 reward types from this group, in any quantity allowed by each reward''s own quota.\" Re-redeeming a reward the user already owns in the group does **not** grow the distinct count — only a brand-new `reward_id` does.\n\n**Counting semantics** (inside `fn_check_reward_group_limits`):\n\n```sql\n-- quantity metric (existing)\nSELECT COALESCE(SUM(qty), 0) FROM reward_redemptions_ledger\nWHERE user_id = :user AND reward_id = ANY(:sibling_ids)\n  AND redeemed_status = true AND cancelled IS NOT TRUE\n  AND created_at >= :window_start;\n\n-- distinct_reward metric (new)\nSELECT COUNT(DISTINCT reward_id) FROM reward_redemptions_ledger\nWHERE user_id = :user AND reward_id = ANY(:sibling_ids)\n  AND redeemed_status = true AND cancelled IS NOT TRUE\n  AND created_at >= :window_start;\n-- Increment by 1 only if :reward_id is NEW to the user in window, else 0.\n```\n\nBoth queries use the partial index `idx_redemptions_group_check_active` on\n`(user_id, reward_id, created_at) WHERE redeemed_status AND NOT cancelled`.\n\n**Configuration Guardrail**: `bff_upsert_reward_group_with_limits` rejects the unsatisfiable combination where, on the same group at `scope = user`, `max_distinct > group_quantity`. Example: \"pick 2 distinct types\" with \"total 1 redemption allowed\" is contradictory — returns error code `CONFLICTING_GROUP_LIMITS`.\n\n**CHECK Constraint**: `transaction_limits_metric_entity_ok` enforces that `metric = ''distinct_reward''` is only allowed when `entity_type = ''reward_group''` AND `scope = ''user''`.\n\n**Summary Matrix** (business-visible outcomes):\n\n| Max Distinct | Group Qty (user) | Reward Qty (user) | Behavior |\n|---|---|---|---|\n| 1 | — | 1 per reward | User picks **one** type, up to 1 unit. |\n| 1 | — | N per reward | User picks **one** type, up to N units. |\n| M (>1) | — | 1 per reward | User picks M types, 1 unit each. |\n| M (>1) | — | N per reward | User picks M types, up to N units each. |\n| 1 | 1 | — | User redeems 1 unit total, locked to one type. |\n| 1 | N | — | User redeems up to N units, **all of the same type**. |\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Reward.md#L485 Database Schema", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "309ed185e14e700e850bee2fd42c3b754219a1cfa23264fe7be7b859ccaf984e", "truncated": true}, "is_active": true}, {"id": "e2a200fb-811d-538b-ae02-e3585cd9c54e", "feature_slug": "rewards", "title": "2. Key Concepts", "content": "**Reward** — A redeemable item defined by a merchant with a name, points cost, eligibility rules, and fulfillment method. Example: \"Free Coffee Voucher — 50 points.\"\n\n**Redemption** — The act of a member exchanging points for a reward. Creates a ledger record with a unique code (e.g., RWD000123). Each redemption tracks two independent statuses: `redeemed_status` (points deducted, reward claimed) and `used_status` (reward actually consumed at store/online). A redemption can be redeemed but not yet used. Example: Member spends 50 points → `redeemed_status=true, used_status=false` → presents voucher at store → `used_status=true`.\n\n**Eligibility** — The first layer of the two-layer system: a binary check determining WHO can see and redeem a reward. Controlled by allowed tiers, personas, user types, tags, and birth months. Empty filter = everyone allowed.\n\n**Dynamic Points** — The second layer: determines HOW MANY points a specific member pays. A matching engine evaluates conditions across four dimensions (tier, user type, persona, tags) and picks the most specific match. Example: A condition \"Gold + Student = 40 pts\" beats \"Gold = 60 pts\" because it matches more dimensions.\n\n**Specificity Scoring** — How the dynamic points engine ranks conditions. Each matched dimension adds to the score (tier: +1000, user_type: +100, persona: +10, tags: +1). Highest total specificity wins. Ties broken by priority, then lowest points (customer-favorable).\n\n**Visibility** — Controls where a reward appears. `user` = public catalog (members browse and redeem). `admin` = internal only (staff redeems on behalf of member at counter). `campaign` = push-only, never in the browse catalog; delivered to members through AMP workflows or admin push — members see them only in \"my redemptions\" after receiving. Consolidates the legacy QR coupon model.\n\n**Fulfillment Method** — How the reward is delivered: `digital` (codes/vouchers), `shipping` (physical delivery), `pickup` (collect at store), `printed` (self-print).\n\n**Stock Control** — When enabled, limits the total number of redemptions available. When disabled, the reward is unlimited.\n\n**Promo Code** — A unique code from a pre-uploaded pool, assigned to the member upon redemption. When enabled, each redemption pulls one code from the pool. Example: Partner discount code \"NIKE-ABC123.\"\n\n**Redemption Window** — Optional start/end dates during which redemption is allowed. Outside this window, the reward is visible but not redeemable.\n\n**Transaction Limits** — Rules capping how many times a reward can be redeemed. Scoped by `per_user`, `per_merchant`, or `per_transaction`, and by time unit (`day`, `week`, `month`, `year`, `lifetime`).\n\n**Multi-Quantity Redemption** — Redeeming N units in one transaction. With promo codes: creates N separate ledger records (one code each). Without promo codes: creates 1 record with qty=N. Range: 1–1000.\n\n**Online Store Distribution** — A free-text array (`online_store[]`) tagging which external storefronts display this reward (e.g., `shopify`, `lazada`). Enables the marketplace integration.\n\n**Burn Rate** — Points spent on this reward (from the Currency domain perspective). See Currency guide.\n\n**Reward Category** — Merchant-defined grouping for organizing the catalog (e.g., \"Food & Beverage\", \"Electronics\").\n\n**Fallback Points** — Default points cost when no dynamic condition matches the member. If `require_points_match` is true and no condition matches, redemption is blocked instead.\n\n**Fulfillment Status** — Tracks physical delivery progress independently of redeemed/used: `pending` → `shipped` → `delivered` → `completed` (or `cancelled`/`reject`). See Section 6c for full status model.\n\n**Expiration Modes** — How redeemed rewards expire: `relative_days` (X days after redemption), `relative_mins` (flash rewards with countdown timer for immediate in-store use), `absolute_date` (fixed date for all).", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/rewards.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5a9311faecbe28e01b9073a398db02c9c6eb7c5107465bae08cc895eb0413932", "truncated": false}, "is_active": true}, {"id": "d4ed3cfe-58ae-5f46-8da2-93acd8c2592e", "feature_slug": "rewards", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch**: \"Rewards let your members spend their earned points on items you choose — vouchers, products, experiences. You control who can redeem (by tier, persona, or birthday), how many points it costs (even different prices for different member segments), and how many can be claimed.\"\n\n**Top 5 support questions:**\n\n\n| Question                               | Answer                                                                                                                             |\n| -------------------------------------- | ---------------------------------------------------------------------------------------------------------------------------------- |\n| \"Members can''t see the reward\"         | Check visibility (must be `user`), eligibility filters (are their tiers/personas included?), and redemption window dates           |\n| \"Redemption says ''insufficient codes''\" | Promo code pool is exhausted — upload more codes or disable promo code assignment                                                  |\n| \"Member was charged wrong points\"      | Dynamic pricing matched a different condition than expected — check the points conditions table and the member''s tier/persona/tags |\n| \"Reward shows 0 points required\"       | No conditions matched AND `require_points_match` is false AND `fallback_points` is null — this means free redemption by design     |\n| \"Redemption stuck on pending\"          | Async processing may be delayed — check if the event was processed; if fulfillment_status is pending, it''s awaiting staff action   |\n\n\n**Config mistakes → fix:**\n\n\n| Mistake                                      | Symptom                         | Fix                                                      |\n| -------------------------------------------- | ------------------------------- | -------------------------------------------------------- |\n| `require_points_match` = true, no conditions | Redemption blocked for everyone | Add at least one condition or set to false with fallback |\n| Promo codes enabled, pool empty              | \"Insufficient codes\" error      | Upload codes or disable promo code assignment            |\n| Window end date in past                      | Visible but unredeemable        | Update end date or remove window                         |\n| Visibility = `admin`                         | Members can''t see it            | Change to `user` or use \"Save and Publish\"               |\n| All eligibility filters too narrow           | Zero redemptions                | Widen filters or leave empty for unrestricted            |\n\n\n**Bug vs misconfiguration**: If the reward appears correctly in admin but members report issues → likely misconfiguration (check eligibility, visibility, window, stock). If the reward doesn''t appear in admin or saves fail → likely a bug (check error messages, contact engineering).", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/rewards.md#L241 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "26764629c47529ab6c5513d04e05db4fd5677dcac3c58fc2febf023ae7ea61fa", "truncated": false}, "is_active": true}, {"id": "d4022ef8-8ff2-5ce3-ad14-e42285bf5897", "feature_slug": "rewards", "title": "1. Overview", "content": "Rewards are redeemable items in the loyalty marketplace — the primary way members spend the points they''ve earned. A merchant creates rewards (vouchers, physical products, digital codes, experiences) and assigns a points cost. Members browse the catalog, pick a reward, and exchange their points for it. This is the \"spend\" side of the earn-and-burn loop that keeps members engaged.\n\nFor merchants, rewards solve a core retention problem: giving customers a tangible reason to stay loyal. Instead of flat discounts, merchants can offer personalized pricing — a Gold-tier member might pay 60 points for a reward that costs a Silver member 80 points. Eligibility filters let merchants target specific segments (tiers, personas, birth months), and stock control prevents over-redemption. The system handles the full lifecycle from catalog display through redemption to fulfillment tracking, including multi-channel distribution to external storefronts like Shopify.\n\nKey differentiators: (1) **dynamic points pricing** — a multi-dimensional matching engine finds the most favorable price per member; (2) **async redemption** — immediate acknowledgment while the backend processes atomically, enabling high-concurrency flash campaigns; (3) **multi-quantity redemption** — bulk redemption with intelligent promo code pool management; (4) **marketplace distribution** — rewards published to external e-commerce platforms alongside the native app.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/rewards.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "1e8edd751df39b7df1d85ab1a326ef333c43a613162308c5e4c9b34a71a71e6e", "truncated": false}, "is_active": true}, {"id": "1cbc6045-a1b7-5142-920d-dcf421591d64", "feature_slug": "rewards", "title": "8. Related Features", "content": "| Feature          | Connection to Rewards                                                                                                                                            |\n| ---------------- | ---------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| Currency         | Points are deducted from the member''s wallet upon redemption. See `Currency.md`.                                                                                 |\n| Tier             | Eligibility can be tier-gated; dynamic pricing can vary by tier. See `Tier.md`.                                                                                  |\n| Tag & Persona    | Eligibility and dynamic pricing dimensions. Persona-aware field filtering affects eligibility checks. See `Tag_and_Persona.md`.                                  |\n| Mission          | Missions can grant rewards as completion prizes. Mission-only rewards use `campaign` visibility. See `Mission.md`.                                               |\n| AMP Workflows    | Campaign-visibility rewards are distributed to members through AMP rule-based or AI-driven workflows. See `AMP - Rule Based.md`.                                 |\n| Translation      | Reward display content supports multi-language via the translation system. See `Translation_System.md`.                                                          |\n| Marketplace      | Rewards can be distributed to external storefronts (Shopify, Lazada, etc.) via `online_store[]` and marketplace channel connections. See `MARKETPLACE_SETUP.md`. |\n| Forms            | Profile completion (form fields) can be a prerequisite for eligibility when persona-aware filtering is active. See `Forms.md`.                                   |\n| Activity/Earning | Members earn points through activities, which they then spend on rewards — the earn-and-burn loop. See `Activity_Based_Earning.md`.                              |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/rewards.md#L401 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "2dcc33c52bf792c9d1865ecd53fe277c5f9c205b724fd404cf7c5a1efe6196ea", "truncated": false}, "is_active": true}, {"id": "5c07a355-3b11-510d-9522-6633d505579d", "feature_slug": "rewards", "title": "Redemption Process Flow", "content": "### Complete Redemption Flow with Dynamic Points\n\n```mermaid\nsequenceDiagram\n    participant U as User\n    participant UI as UI Layer\n    participant API as Redemption API\n    participant RR as redeem_reward_with_points()\n    participant EV as Eligibility Validator\n    participant CP as calculate_redemption_points()\n    participant LE as Limit Enforcer\n    participant PM as Promo Manager\n    participant WM as Wallet Manager\n    participant DB as Database\n    \n    U->>UI: Select Reward\n    UI->>API: Request Redemption\n    API->>RR: redeem_reward_with_points(user_id, reward_id, qty)\n    \n    RR->>DB: Fetch Reward Details\n    DB-->>RR: reward_master record\n    \n    RR->>DB: Fetch User Profile\n    DB-->>RR: user with tier, type, persona, tags\n    \n    RR->>EV: Check Eligibility\n    EV->>EV: Check Tier\n    EV->>EV: Check User Type\n    EV->>EV: Check Persona\n    EV->>EV: Check Tags\n    EV->>EV: Check Birth Month\n    EV->>EV: Check Time Window\n    EV-->>RR: Eligibility Result\n    \n    alt Not Eligible\n        RR-->>API: Error: Not Eligible\n        API-->>UI: Show Error\n        UI-->>U: Display Reason\n    else Eligible\n        RR->>CP: Calculate Points\n        CP->>CP: Get User Attributes\n        CP->>CP: Find Conditions\n        CP->>CP: Evaluate Dimensions\n        CP->>CP: Apply Matching Logic\n        CP-->>RR: Points Required\n        \n        RR->>WM: Check Balance\n        WM->>DB: Get Points Balance\n        DB-->>WM: Current Balance\n        WM-->>RR: Balance Check Result\n        \n        alt Insufficient Points\n            RR-->>API: Error: Need More Points\n            API-->>UI: Show Required vs Available\n            UI-->>U: Display Points Needed\n        else Sufficient Points\n            RR->>LE: Check Limits\n            LE->>DB: Count Previous Redemptions\n            DB-->>LE: Redemption Count\n            LE->>LE: Calculate Window\n            LE->>LE: Check Against Limits\n            LE-->>RR: Limit Check Result\n            \n            alt Limit Exceeded\n                RR-->>API: Error: Limit Exceeded\n                API-->>UI: Show Limit Info\n                UI-->>U: Display Remaining\n            else Within Limits\n                opt Promo Code Required\n                    RR->>PM: Request Promo Code\n                    PM->>DB: Get Available Code\n                    DB-->>PM: Promo Code\n                    PM->>DB: Mark as Redeemed\n                    PM-->>RR: Assigned Code\n                end\n                \n                RR->>RR: Calculate Expiration\n                \n                loop For Each Quantity\n                    RR->>DB: Create Redemption Record\n                    DB-->>RR: Redemption ID\n                end\n                \n                RR->>WM: Deduct Points\n                WM->>DB: Create Wallet Ledger Entry\n                WM->>DB: Update Balance\n                WM-->>RR: Deduction Success\n                \n                RR-->>API: Success Response\n                API-->>UI: Redemption Details\n                UI-->>U: Show Success\n            end\n        end\n    end\n```\n\n### Multi-Quantity Redemption Implementation\n\nThe system supports redeeming multiple quantities of the same reward in a single transaction, with intelligent handling based on promo code requirements.\n\n#### Architecture Flow\n\n```\n┌─────────────────────────────────────────────────────────────────┐\n│                         FRONTEND                                │\n│  POST /redemptions { reward_id, quantity: 5 }                  │\n└────────────────────────────┬────────────────────────────────────┘\n                             │\n                             ↓\n┌─────────────────────────────────────────────────────────────────┐\n│                    RENDER API (crm-api)                         │\n│  1. Validate JWT (extract user_id, merchant_id)                │\n│  2. Validate reward_id and quantity (1-1000)                   │\n│  3. Publish to Kafka: { event_id, user_id, reward_id,         │\n│                         quantity, merchant_id, timestamp }      │\n│  4. Return: { success: true, event_id }                        │\n└────────────────────────────┬────────────────────────────────────┘\n                             │\n                             ↓ (Kafka: reward_redemptions topic)\n                             │\n┌─────────────────────────────────────────────────────────────────┐\n│               EVENT PROCESSOR (crm-event-processors)            │\n│  1. Consume Kafka event                                         │\n│  2. Extract: user_id, reward_id, quantity, merchant_id         │\n│  3. Check idempotency (already processed?)                     │\n│  4. Call Supabase RPC:                                          │\n│     redeem_reward_with_points(                                  │\n│       p_reward_id, p_quantity, p_user_id, p_merchant_id        │\n│     )                                                            │\n│  5. Handle retry on transient errors                           │\n└────────────────────────────┬────────────────────────────────────┘\n                             │\n                             ↓\n┌─────────────────────────────────────────────────────────────────┐\n│          SUPABASE (redeem_reward_with_points function)          │\n│  1. Validate eligibility (tier, persona, tags)                 │\n│  2. Calculate points (multi-dimensional matching)              │\n│  3. Check user balance                                          │\n│  4. Branch based on promo codes:                                │\n│                                                                  │\n│     IF reward has promo codes:                                  │\n│       ├─ Check pool availability (need N codes)                │\n│       ├─ Reserve N codes atomically (FOR UPDATE SKIP LOCKED)   │\n│       ├─ Create N ledger records (qty=1 each)                  │\n│       ├─ Assign unique promo code to each                      │\n│       └─ Mark each code as redeemed                            │\n│                                                                  │\n│     IF reward has NO promo codes:                               │\n│       ├─ Create 1 ledger record (qty=N)                        │\n│       └─ Use default promo code or NULL                        │\n│                                                                  │\n│  5. Deduct points via wallet system                            │\n│  6. Return success with all redemption details                 │\n└─────────────────────────────────────────────────────────────────┘\n```\n\n#### Quantity Handling Patterns\n\n**Pattern A: Reward WITHOUT Promo Codes**\n- Creates **1 ledger record** with `qty = N`\n- Single redemption code (e.g., RWD000123)\n- Points deducted once: `points_per_unit × quantity`\n\n**Example:**\n```sql\n-- Request: quantity = 5\n-- Result: 1 record\nid: evt-123\nqty: 5\npromo_code: NULL\npoints_deducted: 500\ncode: RWD000123\n```\n\n**Pattern B: Reward WITH Promo Codes**\n- Creates **N ledger records** with `qty = 1` each\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Reward.md#L1189 Redemption Process Flow", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "6f9be60c8511d889a053288f7599ccf3e9a3657cc992ec850a413c6cf15116ab", "truncated": true}, "is_active": true}, {"id": "84de3090-969f-5638-b93b-72070bb2b714", "feature_slug": "rewards", "title": "System Architecture", "content": "### Architectural Overview\n\nThe Reward Redemption System is architected as a modular, event-driven platform with clear separation of concerns:\n\n1. **Presentation Layer**: User interfaces for reward browsing and redemption\n2. **Service Layer**: Business logic orchestration and validation\n3. **Calculation Engine**: Dynamic points pricing and condition matching\n4. **Data Layer**: Transactional storage with audit trails\n5. **Integration Layer**: Cross-system coordination with Currency, Tier, and Persona systems\n\n### High-Level Architecture Diagram\n\n```mermaid\ngraph TB\n    subgraph \"User Interface Layer\"\n        UI1[Mobile App]\n        UI2[Web Portal]\n        UI3[Admin Dashboard]\n    end\n    \n    subgraph \"API Layer\"\n        API1[Reward Catalog API]\n        API2[Redemption API - Render]\n        API3[Fulfillment API]\n    end\n    \n    subgraph \"Event Streaming Layer\"\n        ES1[Kafka: reward_redemptions topic]\n        ES2[Event Processor Worker]\n    end\n    \n    subgraph \"Business Logic Layer\"\n        BL1[redeem_reward_with_points]\n        BL2[Eligibility Validator]\n        BL3[Points Calculator]\n        BL4[Limit Enforcer]\n        BL5[Promo Code Manager]\n        BL6[Wallet Manager]\n    end\n    \n    subgraph \"Points Calculation Engine\"\n        PC1[calculate_redemption_points]\n        PC2[Multi-Dimensional Matcher]\n        PC3[Fallback Handler]\n        PC4[Persona Validator]\n    end\n    \n    subgraph \"Data Layer\"\n        DL1[reward_master]\n        DL2[reward_points_conditions]\n        DL3[reward_redemptions_ledger]\n        DL4[reward_promo_code]\n        DL5[transaction_limits]\n        DL6[user_wallet]\n        DL7[wallet_ledger]\n    end\n    \n    subgraph \"Integration Layer\"\n        INT1[Currency System]\n        INT2[Tier System]\n        INT3[Persona System]\n        INT4[Tag System]\n        INT5[Notification Service]\n        INT6[Supabase Realtime: postgres_changes + Broadcast]\n    end\n    \n    UI1 --> API1\n    UI1 --> API2\n    UI2 --> API1\n    UI2 --> API2\n    UI3 --> API3\n    \n    API2 --> ES1\n    ES1 --> ES2\n    ES2 --> BL1\n    \n    API1 --> BL2\n    API3 --> DL3\n    \n    BL1 --> BL2\n    BL1 --> BL3\n    BL1 --> BL4\n    BL1 --> BL5\n    BL1 --> BL6\n    \n    BL3 --> PC1\n    PC1 --> PC2\n    PC1 --> PC3\n    PC1 --> PC4\n    \n    BL2 --> DL1\n    BL2 --> INT2\n    BL2 --> INT3\n    BL2 --> INT4\n    BL3 --> DL2\n    BL4 --> DL5\n    BL5 --> DL4\n    BL6 --> DL6\n    BL6 --> DL7\n    \n    DL3 --> INT6\n    INT6 --> UI1\n    INT6 --> UI2\n    \n    API3 --> INT5\n    \n    style UI1 fill:#e3f2fd\n    style BL1 fill:#fff3e0\n    style PC1 fill:#e8f5e9\n    style DL1 fill:#e1f5fe\n    style INT1 fill:#fce4ec\n    style ES1 fill:#fff9c4\n    style ES2 fill:#fff9c4\n```\n\n### Asynchronous Processing Model\n\nThe system uses an **event-driven architecture** for redemption processing to ensure reliability and scalability:\n\n**Request Flow:**\n1. Frontend → Render API (immediate response with `event_id`)\n2. Render API → Kafka topic (`reward_redemptions`)\n3. Event Processor → Consumes from Kafka\n4. Event Processor → Calls Supabase RPC function (`redeem_reward_with_points`)\n5. **On success**: Supabase creates ledger records → Supabase Realtime `postgres_changes` INSERT on `reward_redemptions_ledger` → Frontend receives success\n6. **On failure**: Event Processor → Supabase Realtime **Broadcast** (HTTP) on channel `redemption:{user_id}` → Frontend receives error with title/description\n\n**Frontend Notification Architecture:**\n- **Success path**: Uses Supabase Realtime `postgres_changes` (INSERT on `reward_redemptions_ledger`) — triggered by the database write itself\n- **Failure path**: Uses Supabase Realtime **Broadcast** (no database write) — the Event Processor sends an HTTP broadcast via `POST /realtime/v1/api/broadcast` with the error details\n- **Timeout fallback**: Frontend applies a ~15s timeout — if neither success nor failure arrives, shows a generic \"processing\" message\n- Broadcast is **ephemeral** (fire-and-forget, not persisted). If the user is not connected when the failure message is sent, they simply won''t see it. This is safe because on failure, nothing changed in the database.\n\n**Benefits:**\n- **Non-blocking**: UI responds immediately (<50ms)\n- **Reliable**: Kafka guarantees message delivery\n- **Scalable**: Parallel processing of redemptions — 10k users hold WebSocket connections, not HTTP polls\n- **Resilient**: Automatic retry on transient failures (up to 5 retries with exponential backoff)\n- **Observable**: Full event trail for debugging\n- **Complete feedback**: Both success AND failure are communicated to the frontend in real-time\n\n### Component Relationships\n\n#### Data Flow\n1. **Catalog Browse**: User → API → Eligibility Check → Points Calculation → Display\n2. **Redemption**: User → Validation → Points Deduction → Code Assignment → Ledger Entry\n3. **Fulfillment**: Redemption → Status Update → Notification → Completion\n\n#### Integration Points\n- **Currency System**: Points balance and transaction management\n- **Tier System**: Customer segmentation for eligibility\n- **Persona System**: Business profile validation\n- **Tag System**: Behavioral targeting\n- **Notification Service**: Redemption confirmations\n\n### Core Components\n\n#### Redemption Service\n\n**Function: `redeem_reward_with_points`**\n- **Purpose**: Central orchestrator for reward redemption flow\n- **Input**: User ID, Reward ID, optional delivery address\n- **Processing**:\n  1. Validate reward exists and is active\n  2. Check comprehensive eligibility (tier, type, persona, tags)\n  3. Calculate dynamic points using multi-dimensional matching\n  4. Verify user has sufficient points\n  5. Enforce redemption limits (user and global)\n  6. Assign promo code from pool if required\n  7. Deduct points via Currency System\n  8. Create redemption ledger entry\n  9. Initialize fulfillment tracking\n- **Output**: Redemption ID, promo code (if applicable), points deducted\n\n#### Points Calculation Engine\n\n**Function: `calculate_redemption_points`**\n- **Purpose**: Determine exact points required for specific user\n- **Input**: Reward ID, User ID\n- **Algorithm**:\n  1. Gather user dimensions (tier, type, persona, tags)\n  2. Retrieve all active conditions for reward\n  3. Score conditions by specificity (4 dims > 3 dims > 2 dims > 1 dim)\n  4. Apply priority weighting within same specificity\n  5. Select lowest points at highest matched specificity\n  6. Return fallback if no conditions match\n- **Output**: Points required, matched condition ID, condition details\n\n#### Eligibility Validator\n\n**Function: `check_reward_eligibility_enhanced`**\n- **Purpose**: Comprehensive eligibility verification\n- **Input**: Reward ID, User ID\n- **Validations**:\n  - Tier membership (if restricted)\n  - User type compatibility\n  - Persona qualification with type consistency\n  - Tag requirements (all required tags must be present)\n  - Time window constraints\n  - Birthday month (if applicable)\n  - Stock availability\n  - Promo code pool status\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Reward.md#L249 System Architecture", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "6045b9daa3f44a403c4baa826e3bee5c8279925eb16b4f2ddd71e584eec9bfa3", "truncated": true}, "is_active": true}, {"id": "e25492be-4339-5529-8489-37a9659617cc", "feature_slug": "rewards", "title": "Reward Domain Domain Reference", "content": "**Keywords:** reward, redeem, redemption, voucher, coupon, promo code, points required, fulfillment, eligibility, stock, reward catalog, dynamic points, multi-quantity, used status, redeemed status, online store, Shopify discount, reward_group, group limit, shared limit, cross-reward limit, is_featured, groups map, group usage, redeemed_reward_ids, frontline, redemption_usage_log, admin_user_id\n**Source:** `Reward.md`\n|---|---|---|\n| Function | Parameters | Returns |\n|---|---|---|\n| `api_get_rewards_full_cached(p_language?, p_persona_id?)` | optional language + persona filter | `{ data[], categories[], groups{}, cache_hit, ... }` |\n| `api_get_my_reward_group_usage()` | none (user from JWT) | `[{ group_id, group_name, is_featured, limits[], redeemed_reward_ids[] }]` |\n| `calculate_redemption_points(user_id, reward_id)` | `user_id uuid`, `reward_id uuid` | Points required, matched condition, calculation details |\n| `check_reward_eligibility_enhanced(user_id, reward_id)` | `user_id uuid`, `reward_id uuid` | Eligibility status, rejection reasons, available quantity |\n| `redeem_reward_with_points(user_id, reward_id, qty)` | `user_id uuid`, `reward_id uuid`, `qty numeric` | Redemption IDs, promo codes, points deducted, expiry |\n| `admin_get_user_redemptions(p_user_id, p_merchant_id, p_filter?, p_limit?, p_offset?, p_search?, p_date_from?, p_date_to?)` | Admin JWT + merchant match | User redemption rows; `all` means non-cancelled, optional search/date filters, store/channel/by metadata |\n| `admin_mark_redemptions_used(p_redemption_ids, p_user_id, p_merchant_id, p_notes?, p_store_id?, p_language?)` | Bulk admin mark-used | `{ used_at, succeeded[], failed[] }`; partial success allowed |\n| `admin_unmark_redemption_used(p_merchant_id, p_redemption_id?, p_redemption_code?, p_reason?, p_store_id?)` | Admin-only revive (Mode A reversal) | `{ redemption_id, status:''redeemed'', reverted_at, previous_used_at, previous_used_store_id }`; flips a used redemption back to redeemed-but-not-used; points stay deducted, promo code stays issued; rejects `cancelled` / `not_used` / multi-use entitlements; logs `redemption_usage_log.action=''reverse_use''` with `source_type=''admin_unmark_used''` |\n| `bff_admin_get_reward_redemption_history(p_user_id, p_store_id?, p_minutes?)` | Front Line redemption history (read or update on `frontline_redemption_reward`) | `{ items[], minutes, store_id, generated_at }`. Returns up to 50 successful, non-cancelled redemptions for the customer, ordered by `COALESCE(used_at, redeemed_at, created_at) DESC`, anchored within `p_minutes` (clamped 1..1440, default 60). Each item includes reward name/image, store ids+names, points/promo, status (`used`/`redeemed`), and `can_unmark_used`. Used by FE Redemption Reward flow to power reverse/unmark actions. |\n| `api_cancel_redemption(p_merchant_id, p_redemption_id?, p_redemption_code?, p_reason?, p_cancelled_by?, p_force_used?)` | Cancel/reverse redemption | Refunds points (writes `wallet_transaction_source_type=''redemption_cancellation''`), returns promo code to pool, sets `cancelled=true`. Default `p_force_used=false` returns `REWARD_ALREADY_USED` for used redemptions; pass `p_force_used=true` to reverse a used redemption (Mode B): unmarks used first then cancels, logs `reverse_use` with `source_type=''cancel_force_used''`. Idempotent on already-cancelled. Multi-use entitlements not in scope. |\n| `api_get_redemption(p_merchant_id, p_redemption_id?, p_redemption_code?, p_store_id?)` | API redemption lookup | Redemption JSON includes store names and redeemed/used-by display names |\n| `bff-mark-redemption-used` | Edge Function: `redemption_id` | Marks used + optional Shopify product enrichment |\n| `bff-get-redemption-detail` | Edge Function: `redemption_id` | Redemption detail + optional Shopify product enrichment |\n**Key Business Rules (summary):**\n- Two-layer architecture: eligibility (WHO) then points pricing (HOW MANY)\n- Dynamic points via 4-dimension matching: tier, user_type, persona, tags — most specific match wins\n- Redemption is async: FE gets `event_id` immediately, listens to Realtime for result\n- Multi-quantity with promo codes creates N separate ledger records; without promo codes creates 1 record with qty=N\n- All-or-nothing: if insufficient promo codes, entire transaction fails\n- Frontline/admin actions carry store and actor audit fields. Redeem with `p_store_id` or `p_source_type=''admin_frontline''` writes `redemption_usage_log.action=''redeem''`; mark-used writes `action=''use''`; lookup with `p_store_id` writes `action=''lookup''`; reversal (either Mode A unmark or Mode B force-cancel) writes `action=''reverse_use''` with `qty_change` set negative. Store IDs are validated against the merchant. Staff actors are stored in `redemption_usage_log.admin_user_id` and `performed_by=auth.uid()::text`; enrichment prefers the redeem actor over lookup-only history and resolves names from `admin_users` first, then `user_accounts`.\n- **Reversal modes**: Mode A (`admin_unmark_redemption_used`) returns a used redemption to the redeemed state without refunding points or returning the promo code — for \"scanner glitch / wrong scan\" recovery. Mode B (`api_cancel_redemption` with `p_force_used=true`) does Mode A first then refunds points and returns the promo code — for \"admin redeemed wrong reward, give the customer their points back\". Stock and group-limit usage restore automatically because availability is derived from `used_status=true AND cancelled IS NOT TRUE`.\n- `online_store[]` is a free-text array for marketplace distribution (e.g., `shopify`, `lazada`)\n- **Reward Groups**: `reward_group` table groups rewards for shared limits. Limits in `transaction_limits` with `entity_type=''reward_group''`. A reward can belong to multiple groups via `reward_master.reward_group_ids UUID[]`. Group limits enforced at redemption time via `fn_check_reward_group_limits`.\n- **`reward_group.is_featured`** (added Apr 2026): boolean, default false. Controls whether the group gets carousel/featured treatment in the FE gallery. Exposed via all three BFF admin functions and both user-facing APIs.", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/reward.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "974a4cb2489f7ce9b2223017da1239bc908c50b53e873cd23640e2651f9dfe14", "truncated": false}, "is_active": true}, {"id": "85205b0f-f904-5fde-a585-b4f559599e9f", "feature_slug": "rewards", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n\n| Config                                                                  | Expected behavior                                        |\n| ----------------------------------------------------------------------- | -------------------------------------------------------- |\n| `visibility = admin`                                                    | Reward absent from member catalog, visible in admin list |\n| `visibility = user` + `allowed_tier = [Gold]`                           | Only Gold-tier members see and can redeem                |\n| `require_points_match = true`, no conditions                            | All redemptions fail with match error                    |\n| `require_points_match = false`, `fallback_points = null`, no conditions | Redemption succeeds with 0 points                        |\n| `stock_control = true`, stock = 0                                       | Redemption fails (out of stock)                          |\n| `assign_promocode = true`, pool empty                                   | Redemption fails (\"insufficient codes\")                  |\n| `redeem_window_end` in past                                             | Reward visible, redemption blocked                       |\n| Transaction limit: per_user, 2/month, user already redeemed 2           | Third redemption blocked                                 |\n| Multi-qty = 5, promo pool has 3 codes                                   | Entire transaction fails (all-or-nothing)                |\n| Multi-qty = 5, no promo codes                                           | 1 ledger record with qty=5                               |\n| Multi-qty = 5, promo codes available                                    | 5 ledger records with qty=1 each, unique codes           |\n\n\n**Business rules as assertions:**\n\n- ASSERT: When member redeems, points deducted = calculated points × quantity\n- ASSERT: Dynamic pricing selects condition with highest specificity score\n- ASSERT: When specificity ties, higher priority wins; when priority ties, lowest points wins\n- ASSERT: Promo code redemption creates exactly N ledger records for qty=N\n- ASSERT: Non-promo redemption creates exactly 1 ledger record regardless of qty\n- ASSERT: Redemption within window succeeds; outside window fails\n- ASSERT: After successful redemption, `redeemed_status = true`, `used_status = false`\n- ASSERT: After mark-as-used, `used_status = true`\n- ASSERT: \"Save and Publish\" sets visibility to `user` regardless of dropdown value\n\n**Status model (two independent tracks):**\n\n| Track | Field | Values | Meaning |\n|---|---|---|---|\n| Claim | `redeemed_status` | `false` → `true` | Points deducted, reward claimed |\n| Usage | `used_status` | `false` → `true` | Reward consumed (voucher used at store, code entered) |\n| Fulfillment | `fulfillment_status` | `pending` → `shipped` → `delivered` → `completed` | Physical delivery progress |\n| Fulfillment (alt) | `fulfillment_status` | `pending` → `cancelled` or `reject` | Failure paths |\n\n- A reward can be `redeemed_status=true, used_status=false` indefinitely (claimed but not yet used)\n- `used_status` can only become `true` after `redeemed_status=true`\n- `fulfillment_status` is independent — a `delivered` reward can still be `used_status=false`\n\n**Member-facing UI states** (History drawer sub-filters):\n- \"My Reward\" = `redeemed_status=true, used_status=false, not expired`\n- \"Used\" = `used_status=true`\n- \"Expired\" = `use_expire_date` has passed and `used_status=false`\n\n**Error states and cross-feature scenarios to test:**\n\n- Insufficient points balance; insufficient promo codes in pool; stock depleted\n- Transaction limit exceeded (per_user and per_merchant scopes)\n- Ineligible tier/persona/tags/birth month; outside redemption window\n- No matching condition when `require_points_match = true`\n- Concurrent race condition (two members, one stock item — exactly one succeeds)\n- Realtime timeout (15s, no event) → \"Processing\" toast shown\n- Tier upgrade → points cost changes on same reward\n- Persona change → eligibility and dynamic pricing both update\n- Redemption deducts from correct currency wallet, balance updates in real-time\n- Reward with `online_store = [''shopify'']` bound to discount code → appears on Shopify", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/rewards.md#L241 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "3801bb4c5365ded26e815b8d3497cb563832c884d50786317e60477094cba340", "truncated": false}, "is_active": true}, {"id": "734657a2-9cf4-56cf-9e33-6b56472bbf5d", "feature_slug": "rewards", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n**Route map:**\n\n| Page / Component | Current route | Data source |\n|---|---|---|\n| Rewards catalog | `/rewards` | `api_get_rewards_full_cached(p_language, p_persona_id?)` |\n| Reward detail drawer | Bottom-sheet on `/rewards` | Same cached data + eligibility info |\n| Redemption slip drawer | Bottom-sheet on `/rewards` | Realtime INSERT payload |\n| History drawer | Bottom-sheet from Homepage/Profile | `bff_get_reward_history(p_filter, p_limit, p_offset, p_language)` |\n\n### 5a. Browse Rewards\n\n1. Member opens the reward catalog — 2-column card grid layout\n2. **Category filter bar** at top: horizontal chips (\"All\", \"Discount\", \"Voucher\", etc.) from `reward_category`\n3. Each card shows: reward image, name, points required (`points.fallback`), availability\n4. Tapping a category chip filters the grid instantly (client-side)\n\n### 5b. View Reward Detail\n\n1. Member taps a reward card → **bottom-sheet drawer** slides up\n2. Drawer shows: hero image (full-width, 220px with gradient overlay), reward name, headline, redemption window dates, points required, eligibility chips (tier colors, persona names), description body, terms & conditions\n3. Footer: error message area + **\"Redeem\"** CTA button\n4. If ineligible: reason displayed, CTA disabled\n\n### 5c. Redeem a Reward\n\n1. Member taps \"Redeem\" → **confirmation popup** (\"Redeem Reward Now?\") with Cancel / Confirm\n2. On Confirm: app POSTs to Render API → receives 200 (queued, not completed)\n3. Detail drawer closes → **loading overlay with spinner** appears (state: `pending`)\n4. App listens on Supabase Realtime channel `redemption:{userId}` (subscribed on page mount, not per-redemption)\n5. **On success** (Realtime INSERT on `reward_redemptions_ledger`): success toast + **\"Use Now\" confirm drawer** opens with two options: \"Use now\" or \"See wallet\"\n6. **On failure** (Realtime broadcast `redemption_failed`): error toast with title + description from backend\n7. **On timeout** (15 seconds, no event): \"Processing\" toast — check rewards history\n\n### 5d. Use a Redeemed Reward\n\n1. From \"Use Now\" drawer or History: **Redemption Slip drawer** opens\n2. Slip shows: reward image (circular), reward name, status badge (\"Not yet used\" / \"Used\"), redemption date, and code in three formats via tabbed display: **Code** (text) / **Barcode** / **QR Code**\n3. Code source: `promo_code` if assigned, otherwise system-generated redemption code\n4. If `use_expire_mode = relative_mins`: live **countdown timer** displayed (flash reward)\n5. Member presents code to staff or enters at checkout → `api_mark_redemption_used` marks `used_status = true`\n\n### 5e. View Redemption History\n\n1. Member opens **History drawer** (from Homepage or Profile) → selects **Reward** tab\n2. Sub-filter chips: \"My Reward\" (redeemed, not yet used) / \"Used\" / \"Expired\"\n3. Each row shows: reward image, name, redemption code, date, points spent, status\n4. Redeemed-but-not-used items show a **\"Use\" action button** → opens Redemption Slip drawer\n5. Infinite scroll pagination", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/rewards.md#L188 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7cfacc54aa614dbc7bc5aa9c48a5f9b1bf5cdad57cade28ea39f94066dd1958c", "truncated": false}, "is_active": true}, {"id": "5239cac5-33a3-5479-b945-251aa980fd35", "feature_slug": "rewards", "title": "6b. For Marketing", "content": "**Value proposition**: Rewards transform passive point balances into active engagement. Members earn points through purchases and activities, then redeem them for meaningful benefits — creating a cycle that drives repeat visits. The dynamic pricing engine lets merchants offer VIP-level personalization (\"Gold members pay fewer points\") without manual management.\n\n**Use-case stories:**\n\n1. **Café chain** — Creates \"Free Coffee\" (50 pts), \"Birthday Cake Slice\" (birthday month only, 30 pts), and \"VIP Tasting Event\" (Platinum tier only, 200 pts). Birthday rewards drive a 40% visit increase in members'' birth months.\n\n2. **Fashion retailer** — Lists rewards across tiers: Bronze gets 10% vouchers (100 pts), Gold gets early-access sale passes (80 pts), Platinum gets personal styling sessions (500 pts). Tier-gated exclusivity motivates upgrades.\n\n3. **Flash sale campaign** — Merchant creates a limited-stock reward with `relative_mins` expiry (30-minute countdown timer on the redemption slip). The async architecture handles thousands of simultaneous redemptions without timeouts — members get instant confirmation while the backend processes atomically. Creates urgency to use the reward immediately in-store.\n\n4. **B2B distributor** — Uses persona-based pricing: \"Corporate\" persona pays 60 pts for bulk samples, \"SME\" persona pays 40 pts. Promo codes tied to partner discount codes on Shopify, distributed automatically through marketplace integration.\n\n**Metrics merchants care about**: Redemption rate (% of members who redeem), average points spent per redemption, reward popularity ranking, stock depletion rate, promo code utilization rate, time-to-use (redeemed → used duration).\n\n**Differentiators to highlight:**\n- **Dynamic per-segment pricing** — different members see different points costs based on their profile, not a flat rate\n- **Flash campaign ready** — async event-driven architecture handles high concurrency without timeouts, enabling limited-time high-demand promotions\n- **Multi-channel distribution** — same reward published to native app + Shopify + Lazada + BigCommerce simultaneously\n- **Multi-quantity in single transaction** — bulk redemption with atomic promo code assignment\n- **Birthday and persona targeting** — rewards that only appear for the right members at the right time\n- **Real-time confirmation** — members see results within seconds via Realtime push, not polling", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/rewards.md#L241 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f88258028c4e146eb98bb83cd8009d90ee832878a5bf53b51ed616f410574fcd", "truncated": false}, "is_active": true}, {"id": "0f7345c8-38d4-5f65-a486-116690203f27", "feature_slug": "signup-code-validation", "title": "Signup Code Validation Domain Reference", "content": "**Keywords:** signup code, external code, dealer code, corporate code, tax id, code claim, validate code, signup_codes, signup_code_claims, fn_consume_signup_code, bff_validate_signup_code, bff_upload_signup_codes, bff_list_signup_codes, bff_delete_signup_codes, external_code field type, persona-scoped signup, max_consumers, target_user_column\n**Source:** Lives entirely in `requirements/Signup_Login.md` (sections 6–7) and this file. No standalone source doc.\n| `id`                       | uuid PK              | `gen_random_uuid()`                                                                |\n| `merchant_id`              | uuid NOT NULL        | FK `merchant_master`, RLS isolation                                                |\n| `field_config_id`          | uuid NOT NULL        | FK `user_field_config(id)` — must point to a row with `field_type=''external_code''` |\n| `code`                     | text NOT NULL        | Unique per `(field_config_id, code)`                                               |\n| `metadata`                 | jsonb DEFAULT `''{}''` | Preview info shown after Validate **plus** prefill values that auto-fill the user''s profile form. See \"Metadata shape\" below. |\n| `max_consumers`            | int DEFAULT 1        | How many distinct users can claim this code (1 for one-time-use, N for shared)     |\n| `consumed_count`           | int DEFAULT 0        | Atomic counter, capped via CHECK `consumed_count <= max_consumers`                 |\n| `is_active`                | boolean DEFAULT true | Admin-controlled enable/disable                                                    |\n| `created_at`, `updated_at` | timestamptz          | Standard, `trigger_set_updated_at`                                                 |\n| `id`          | uuid PK                     |                                                        |\n| `merchant_id` | uuid NOT NULL               | RLS isolation                                          |\n| `code_id`     | uuid NOT NULL               | FK `signup_codes(id)` — points to one code, not a pool |\n| `user_id`     | uuid NOT NULL               | FK `user_accounts(id)`                                 |\n| `claimed_at`  | timestamptz DEFAULT `now()` |                                                        |\n| `pool_label`         | Admin-facing label shown above the code list. UI-only — not used by any RPC.                                                                                                                                                                                                                                                                                                                   |\n| `max_consumers`      | Default cap when uploading new codes (per-code value can override). `1` = single-use codes, `N>1` = shareable codes, very large = effectively unlimited.                                                                                                                                                                                                                                       |\n| `target_user_column` | If set, the consumed code is written to this column on `user_accounts`. Whitelisted: `external_user_id`, `member_code`, `id_card`. Other values are ignored.                                                                                                                                                                                                                                  |\n| `prefill_schema`     | **Schema-on-pool.** Two arrays of `field_key`s declaring which default fields and which `USER_PROFILE` custom fields each code in this pool may prefill. Set via `bff_set_signup_code_prefill_schema`. Defaults to `{ default: [], custom: [] }` (no prefill allowed). Codes whose `metadata.prefill` includes any key not in this schema are rejected at upload with `KEY_NOT_IN_POOL_SCHEMA`. |\n| `preview`         | Free-form jsonb shown on the FE after Validate succeeds (e.g. confirm the code belongs to \"Acme Corp\"). Not schema-validated. Returned as `data.preview_metadata`.                                                                                                                                                                     |\n| `prefill.default` | Map of `user_field_config.field_key` → value. Keys must be in `pool.config.external_code.prefill_schema.default[]`. Upload rejects any key not in the schema. The FE seeds these into the corresponding default-field inputs after a successful Validate.                                                                              |\n| `prefill.custom`  | Map of `form_fields.field_key` → value, scoped to the merchant''s `USER_PROFILE` template. Keys must be in `pool.config.external_code.prefill_schema.custom[]`. Upload rejects any key not in the schema. The FE seeds these into custom-field inputs.                                                                                  |\n| `bff_validate_signup_code(p_field_key text, p_code text, p_selected_persona_id uuid DEFAULT NULL)`                                                | End-user (FE Validate button)                | `get_current_merchant_id()`, optional `auth.uid()` | Read-only validation. Returns `{valid, preview_metadata, prefill: {default, custom}, already_claimed, remaining_seats}` or structured error. `prefill.*` blocks contain only keys that still resolve against `user_field_config` / `USER_PROFILE.form_fields` for the merchant; deleted/renamed keys are silently dropped. Idempotent for already-claimed codes. |\n| `fn_consume_signup_code(p_user_id uuid, p_field_config_id uuid, p_code text)`                                                                     | Internal (called by `bff_save_user_profile`) | `SECURITY DEFINER`                                 | Atomic consumption: persona check → race-safe `UPDATE ... WHERE consumed_count < max_consumers RETURNING ...` → insert claim → optional `target_user_column` write. Does **not** apply `metadata.prefill` — the FE seeded those values into the form payload, which `bff_save_user_profile` writes through its normal default/custom routing. Raises `SIGNUP_CODE:<code>:<msg>` on failure (rolls back caller''s txn). |\n| `bff_save_user_profile` (extended)                                                                                                                | End-user FE final submit                     | `auth.uid()`                                       | After `user_accounts` upsert, calls `fn_consume_signup_code` for each submitted `external_code` field. Catches `raise_exception` with `SIGNUP_CODE:` prefix and returns structured error. Whole txn rolls back on failure.                               |\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/signup-code-validation.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "signup-code-validation", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "99859c904a20f2fb9cd967e6575a7b5beef5c75d85a618364c868c5d6489b5f3", "truncated": true}, "is_active": true}, {"id": "3fa3f6bf-24a9-516a-9ba5-a77bc8af3de9", "feature_slug": "signup-login", "title": "`form_step` (Frontend state for form navigation)", "content": "**Location:** Frontend variable (e.g., `variables[''f214fed7-7ce4-43f6-888f-251cb10b4191'']`)\n\n**Values:** `\"persona\"` | `\"default_field\"` | `\"custom_field\"` | `\"pdpa\"`\n\n**Purpose:** Track which section of the multi-step form user is currently viewing\n\n**Sequence:** persona → default_field → custom_field → pdpa\n\n**Relationship to `next_step`:**\n- `next_step` = API instruction (what major screen to show)\n- `form_step` = Frontend state (which form section within the profile form)\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Signup_Login.md#L382 `form_step` (Frontend state for form navigation)", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "signup-login", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ce8902e477577962d63f13948c94218dce2d1bb014aa9cc98aedb7db941350bb", "truncated": false}, "is_active": true}, {"id": "6c7664d1-a001-5cc1-83e0-18cb12edcbd7", "feature_slug": "signup-login", "title": "Security Patterns", "content": "### Row Level Security (RLS)\nAll user data filtered by `get_current_merchant_id()` extracted from:\n1. Custom header `x-merchant-id`\n2. JWT claim `merchant_id`\n\n### Function Security\n- All BFF functions: `SECURITY DEFINER`\n- Permissions granted to `authenticated` role\n- Public endpoints: `auth-line` (`verify_jwt: false`)\n- Other edge functions: `verify_jwt: true`\n\n### JWT Structure\n```json\n{\n  \"sub\": \"user_id\",\n  \"merchant_id\": \"uuid\",\n  \"user_id\": \"uuid\",\n  \"phone\": \"+66966564526\",\n  \"line_id\": \"U46fa97...\",\n  \"role\": \"authenticated\",\n  \"aud\": \"authenticated\",\n  \"iss\": \"supabase\",\n  \"exp\": 1234567890\n}\n```\n\n**Expiry:**\n- Access token: 24 hours\n- Refresh token: 30 days\n\n---", "content_format": "markdown", "knowledge_type": "implementation_constraints", "perspectives": ["implementation", "technical", "testing"], "output_uses": ["implementation_brief", "qa_testing", "technical_docs"], "scope": "be", "source_ref": "requirements/Signup_Login.md#L849 Security Patterns", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "constraints", "feature_slug": "signup-login", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c0eb15e18a6fdd7e6f8a9d26a2274c44cb2d924613f5e865510c37c125d95cec", "truncated": false}, "is_active": true}, {"id": "34de75c7-6128-5957-97f0-6c7c28cba5f4", "feature_slug": "signup-login", "title": "Error Handling", "content": "### Common errors from `bff-auth-complete`:\n\n| Error | Reason |\n|-------|--------|\n| `\"merchant_code is required\"` | Missing merchant_code parameter |\n| `\"Invalid merchant_code\"` | merchant_code not in MERCHANT_REGISTRY |\n| `\"Incomplete phone verification parameters\"` | Missing tel, otp_code, or session_id (must provide all 3) |\n| `\"Invalid or expired OTP\"` | OTP validation failed or max attempts exceeded |\n| `\"Credentials belong to different accounts\"` | LINE and tel registered to different users |\n| `\"Failed to create account\"` | Database error during user creation |\n\n### Error handling strategy:\n- Display error message to user\n- Log details for debugging\n- For auth errors: Return to auth screen\n- For profile errors: Allow retry\n\n---", "content_format": "markdown", "knowledge_type": "implementation_constraints", "perspectives": ["implementation", "technical", "testing"], "output_uses": ["implementation_brief", "qa_testing", "technical_docs"], "scope": "be", "source_ref": "requirements/Signup_Login.md#L883 Error Handling", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "constraints", "feature_slug": "signup-login", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e59fbd6358d1b4b4d6a3986f55864fa7d13e782e04351586453ecff7ce348e1a", "truncated": false}, "is_active": true}, {"id": "e93e8f89-9974-567f-8f77-34916439c7a3", "feature_slug": "signup-login", "title": "Function Inventory", "content": "### 1. `bff_get_auth_config(p_merchant_code)`\n**Purpose:** Get merchant''s authentication method configuration\n\n**Input:**\n```json\n{\n  \"merchant_code\": \"newcrm\"\n}\n```\n\n**Output:**\n```json\n{\n  \"auth_methods\": [\"line\", \"tel\"]\n}\n```\n\n**Frontend usage:** Determine which auth UI to show (LINE button, phone input, or both)\n\n---\n\n### 2. `auth-line` (Edge Function)\n**Purpose:** Exchange LINE OAuth code for LINE user profile (does NOT create user or issue JWT)\n\n**Input:**\n```json\n{\n  \"code\": \"LINE_AUTH_CODE\",\n  \"merchant_code\": \"newcrm\", \n  \"redirect_uri\": \"https://...\"\n}\n```\n\n**Output:**\n```json\n{\n  \"success\": true,\n  \"line_user_id\": \"U46fa97...\",\n  \"display_name\": \"John Doe\",\n  \"picture_url\": \"https://...\"\n}\n```\n\n**Frontend usage:** After LINE login callback, exchange code for profile data, then pass to `bff-auth-complete`\n\n**Security:** Public endpoint (`verify_jwt: false`), only requires anon key\n\n---\n\n### 3. `auth-send-otp` (Edge Function)\n**Purpose:** Generate OTP and send SMS via 8x8\n\n**Input:**\n```json\n{\n  \"phone\": \"0966564526\",\n  \"merchant_code\": \"newcrm\"\n}\n```\n\n**Output:**\n```json\n{\n  \"success\": true,\n  \"session_id\": \"uuid-uuid\",\n  \"expires_in\": 600,\n  \"message\": \"OTP sent to +66966564526\"\n}\n```\n\n**Phone normalization:**\n- `0966564526` → `+66966564526`\n- `+660966564526` → `+66966564526` (removes extra 0)\n- `66966564526` → `+66966564526` (adds +)\n\n**Frontend usage:** User enters phone → call this → store `session_id` → show OTP input\n\n**OTP settings:**\n- Length: 6 digits\n- Expiry: 10 minutes\n- Max attempts: 3\n\n---\n\n### 4. `bff-auth-complete` (Edge Function) - **THE CENTRAL HUB**\n**Purpose:** Unified authentication - finds/creates users, links auth methods, checks profile completion, issues JWTs\n\n**Input scenarios:**\n\n**A. LINE only:**\n```json\n{\n  \"merchant_code\": \"newcrm\",\n  \"line_user_id\": \"U46fa97...\"\n}\n```\n\n**B. Tel only:**\n```json\n{\n  \"merchant_code\": \"newcrm\",\n  \"tel\": \"+66966564526\",\n  \"otp_code\": \"123456\",\n  \"session_id\": \"uuid\"\n}\n```\n\n**C. Both (LINE first, then tel):**\n```json\n{\n  \"merchant_code\": \"newcrm\",\n  \"line_user_id\": \"U46fa97...\",\n  \"tel\": \"+66966564526\",\n  \"otp_code\": \"123456\",\n  \"session_id\": \"uuid\"\n}\n```\n\n**D. Link method to existing session:**\n```json\n{\n  \"merchant_code\": \"newcrm\",\n  \"access_token\": \"eyJ...\",\n  \"tel\": \"+66966564526\",\n  \"otp_code\": \"123456\",\n  \"session_id\": \"uuid\"\n}\n```\n\n**Output:**\n\n**Intermediate response (needs more verification):**\n```json\n{\n  \"success\": true,\n  \"next_step\": \"verify_tel\",\n  \"message\": \"Phone verification required\"\n}\n```\n\n**Full response (user created/found, JWT issued):**\n```json\n{\n  \"success\": true,\n  \"next_step\": \"complete_profile_new\",\n  \"user_account\": {\n    \"id\": \"uuid\",\n    \"tel\": \"+66966564526\",\n    \"line_id\": \"U46fa97...\",\n    \"fullname\": null,\n    \"email\": null\n  },\n  \"access_token\": \"eyJ...\",\n  \"refresh_token\": \"uuid-uuid\",\n  \"expires_in\": 86400,\n  \"is_new_user\": true,\n  \"is_signup_form_complete\": false,\n  \"missing\": {\n    \"tel\": false,\n    \"line\": false,\n    \"consent\": true,\n    \"profile\": true,\n    \"address\": false\n  },\n  \"missing_data\": {\n    \"persona\": { ... },\n    \"pdpa\": [ ... ],\n    \"default_fields_config\": [ ... ],\n    \"custom_fields_config\": [ ... ],\n    \"selected_section\": null\n  }\n}\n```\n\n**Logic flow:**\n1. Get merchant config and auth_methods\n2. Normalize tel format\n3. Validate credentials (OTP if tel provided)\n4. Find existing user (by LINE or tel or access_token)\n5. Handle conflicts (LINE and tel belong to different users)\n6. Create new user if not found\n7. Link missing auth methods to existing user\n8. Generate JWT with merchant context\n9. **Early return optimization:** if required auth method is still missing (`verify_line` / `verify_tel`), return immediately (still includes `access_token` + `refresh_token`) and **skip** profile template evaluation\n10. Check profile completion using `bff_get_user_profile_template` (only when auth methods are satisfied); returned field lists are **persona-filtered** for the session JWT—see §5\n11. Determine `next_step` based on profile completion\n12. Build `missing_data` payload (full form or missing-only)\n13. Generate refresh token\n14. If `next_step === \"complete\"`, also merge `get_user_summary()` output into `user_account` (flat)\n15. Return comprehensive response\n\n---\n\n### 5. `bff_get_user_profile_template(p_mode, p_language, p_merchant_code, p_event_code)`\n**Purpose:** Build the user profile form schema (default fields, custom form fields, persona picker structure, PDPA/consent shell, channels/topics items) with translations, then return only the slices appropriate for the **current JWT** and **persona**.\n\n**Where it is used (not only edit profile):**\n- **Signup / post-login profile completion:** After `bff-auth-complete` has issued a session and all required auth methods are satisfied, that flow evaluates profile completion and may call this RPC (or equivalent server-side logic) so `missing_data` reflects the same template the client should render—see step 10 in `bff-auth-complete` above.\n- **Edit profile (standalone screen):** The app may call this RPC directly with `p_mode = ''edit''` and the user’s bearer token so the form is pre-filled from `user_accounts` / `user_address` / `form_responses` / consents / channel flags.\n\n**Input (Postgres parameter order):**\n| Parameter | Default | Role |\n|-----------|---------|------|\n| `p_mode` | `''new''` | `''new''` = empty values (plus optional event pre-fill); `''edit''` = overlay stored user data for fields still present after filtering |\n| `p_language` | `''en''` | Resolved UI language (with fallback to merchant default) |\n| `p_merchant_code` | `null` | If set, resolves merchant via config cache; if `null`, uses session merchant context (`get_current_merchant_id()`) |\n| `p_event_code` | `null` | Optional Syngenta-style event: pre-fills address admin IDs on matching default fields when `p_mode = ''new''` |\n\n**Persona and field visibility (server-side, JWT-driven):**\n- The function reads **`auth.uid()`** and loads **`user_accounts.persona_id`** for that auth user and **current merchant**.\n- Each default field (`user_field_config`) and custom field (`form_fields`) carries **`persona_ids`** in the JSON.\n  - **Universal field:** `persona_ids` is missing, JSON `null`, or an **empty** array → returned for every caller (subject to other flags such as `visible_to_user`).\n  - **Persona-scoped field:** non-empty `persona_ids` → returned only if the user’s `persona_id` is in that list.\n  - **User has no `persona_id`:** only universal fields are returned; persona-scoped fields are omitted.\n- **Field groups:** If, after filtering, a group has **no** remaining fields, that **entire group is omitted** from `default_fields_config` and `custom_fields_config`.\n- **Persona metadata:** The response still includes the full **`persona`** object (groups, personas, `persona_attain`, etc.) so the client can render persona selection; filtering applies to **fields**, not to hiding the persona catalog unless the product layer does so.\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Signup_Login.md#L23 Function Inventory", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "signup-login", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "90f0509b8abb8f5f8e86063b315b20e5a7941a460e4bd60fc42bb2790efcec4b", "truncated": true}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
